CREATE OR REPLACE FUNCTION private.check_account_access()
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare subject uuid:=auth.uid();
begin
 if subject is not null then
  -- A fresh snapshot after acquiring the lock is essential. A transaction with
  -- a fixed snapshot could miss a restriction committed while it was starting.
  if current_setting('transaction_isolation') not in ('read committed','read uncommitted') then
   raise sqlstate '42501' using message='account_access_isolation_unsupported';
  end if;
  if not pg_catalog.pg_try_advisory_xact_lock_shared(private.account_deletion_barrier_key(subject)) then
   raise sqlstate '42501' using message='account_access_transition';
  end if;
  -- This is a separate command inside a VOLATILE function, hence a fresh
  -- READ COMMITTED snapshot. The shared lock lasts through the entire request.
  if not private.account_access_allowed() then
   raise sqlstate '42501' using message='account_access_restricted';
  end if;
 end if;
 perform set_config('sko.account_access_hook_ran','true',true);
 perform set_config('sko.account_access_barrier_ran','data-api-v1',true);
end $function$

