CREATE OR REPLACE FUNCTION public.employee_onboarding_state()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_row public.employee_registration_invites%rowtype;
begin
  if v_user_id is null then
    return null;
  end if;

  select *
  into v_row
  from public.employee_registration_invites
  where auth_user_id = v_user_id
  order by created_at desc
  limit 1;

  if not found then
    return null;
  end if;

  if v_row.status = 'invited'
     and v_row.expires_at < now() then
    update public.employee_registration_invites
    set status = 'cancelled'
    where id = v_row.id;
    v_row.status := 'cancelled';
  end if;

  return jsonb_build_object(
    'invite_id', v_row.id,
    'company_id', v_row.company_id,
    'worker_id', v_row.worker_id,
    'name', v_row.name,
    'phone', v_row.phone_e164,
    'status', v_row.status,
    'expires_at', v_row.expires_at,
    'password_changed_at', v_row.password_changed_at
  );
end;
$function$
